UPDATE payment_allocations AS allocation SET cash_advance_allocation = LEAST(allocation.total_payment - allocation.minimum_payment_portion, selected.amount) FROM transactions AS selected JOIN regz_context ON regz_context.batch_id = selected.transaction_id JOIN balance_components AS component ON component.component_id = selected.transaction_id JOIN statements AS statement_context ON statement_context.statement_id = selected.statement_id JOIN allocation_snapshot_context AS snapshot ON snapshot.account_id = selected.account_id AND snapshot.statement_id = selected.statement_id WHERE allocation.allocation_id = 'ALLOC0000001' AND allocation.account_id = selected.account_id AND selected.transaction_id = (SELECT candidate.transaction_id FROM transactions AS candidate JOIN daily_balances AS balance ON balance.account_id = candidate.account_id AND balance.statement_id = candidate.statement_id AND balance.balance_category = candidate.balance_category WHERE candidate.account_id = allocation.account_id AND candidate.statement_id = allocation.statement_id AND candidate.transaction_type = 'cash_advance' AND balance.balance_date = DATE '2027-01-30' ORDER BY balance.apr_applied DESC LIMIT 1) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.highest_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.remaining_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.classification_mismatches = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.active_programs = 0 OR regz_context.window_programs > 0 OR regz_context.ordinary_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.deferred_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.window_programs = 0 OR regz_context.ordinary_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'deferred_request' OR (regz_context.active_programs > 0 AND regz_context.issuer_elected AND regz_context.request_mismatches = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'secured_request' OR (regz_context.unsecured_request_targets = 0 AND regz_context.issuer_elected AND regz_context.request_mismatches = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.snapshot_date >= regz_context.cycle_end AND regz_context.snapshot_date <= regz_context.credited_date)) AND (regz_context.kind <> 'allocation' OR (regz_context.snapshot_date = regz_context.expected_snapshot_date)) AND (regz_context.kind <> 'allocation' OR (regz_context.unauthorized_changes = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.snapshot_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.protected_reduction <= regz_context.unavoidable_protected_reduction)) AND (regz_context.kind <> 'allocation' OR (regz_context.unavoidable_protected_reduction = 0 OR regz_context.protected_reduction = 0 OR regz_context.other_capacity_remaining = 0)) AND (regz_context.kind <> 'correction' OR regz_context.missing_credit_cents = 0) AND (regz_context.kind <> 'correction' OR regz_context.notice_count > 0) AND (regz_context.kind <> 'allocation' OR (regz_context.effective_apr_mismatches = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.interim_payment_omissions = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.grace_classifications = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.zero_offer_classifications = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.window_start_mismatches = 0)) AND (regz_context.kind <> 'allocation' OR (regz_context.method <> 'default' OR (regz_context.early_expiry_violations = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.request_present OR regz_context.method = 'default')) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_feasibility_errors = 0 AND regz_context.superseding_requests = 0))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'contact' OR (regz_context.affirmative AND regz_context.instruction_count > 0 AND regz_context.contact_channel)))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'form' OR (regz_context.form_completed AND regz_context.request_present AND regz_context.affirmative AND regz_context.instruction_count > 0)))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'reallocation' OR (regz_context.prior_default_allocation AND regz_context.affirmative AND regz_context.contact_channel AND regz_context.instruction_count > 0)))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'agreement_default'))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'application_default'))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (regz_context.request_basis <> 'coupon_default'))) AND (regz_context.kind <> 'allocation' OR (regz_context.method = 'default' OR (NOT regz_context.required_condition)));
